      original.id,
      expect.stringContaining("changed again"),
    );
    expect(api.updateIssue).not.toHaveBeenCalled();
    expect(result).toMatchObject({
      output: { status: "aborted_conflict" },
      terminate: true,
    });
  });

  it("reports an unavailable repository without changing the issue", async () => {
    const api = gateway();
    const tools = linearIssueTools(
      { issueId: original.id, teamId: original.teamId, deliveryId: "delivery" },
      { conflictCount: 0, recordConflict: vi.fn(), gateway: api },
    );

    const result = await tools.reportRepositoryUnavailable.run({
      step: { do: async (_name: string, operation: () => unknown) => operation() },
    } as never);
    expect(api.createIssueComment).toHaveBeenCalledWith(
      original.id,
      expect.stringContaining("no repository is currently available"),
    );
    expect(api.updateIssue).not.toHaveBeenCalled();
    expect(result).toMatchObject({
      output: { status: "repository_unavailable" },
      terminate: true,
    });
  });
});

